/**
 * Tiny path router: literal segments, `:param` captures, and a trailing
 * `*param` catch-all, compiled once at server startup.
 */
export class Router {
    constructor() {
        this.routes = [];
    }
    add(route) {
        this.routes.push({ route, segments: compilePattern(route.pattern) });
    }
    match(method, pathname) {
        const direct = this.matchExact(method, pathname);
        if (direct !== undefined) {
            return direct;
        }
        // HTTP: HEAD may be served by the corresponding GET handler (wget --spider,
        // some load-balancer probes). Without this, GET-only routes return 405.
        if (method === "HEAD") {
            return this.matchExact("GET", pathname);
        }
        return undefined;
    }
    matchExact(method, pathname) {
        const pathSegments = splitPath(pathname);
        for (const { route, segments } of this.routes) {
            if (route.method !== method) {
                continue;
            }
            const params = matchSegments(segments, pathSegments);
            if (params !== undefined) {
                return { route, params };
            }
        }
        return undefined;
    }
    /** True when the path matches some route with a different method. */
    hasPath(pathname) {
        const pathSegments = splitPath(pathname);
        return this.routes.some(({ segments }) => matchSegments(segments, pathSegments) !== undefined);
    }
}
function compilePattern(pattern) {
    const segments = splitPath(pattern).map((part) => part.startsWith(":")
        ? { kind: "param", name: part.slice(1) }
        : part.startsWith("*")
            ? { kind: "rest", name: part.slice(1) }
            : { kind: "literal", value: part });
    const restIndex = segments.findIndex((segment) => segment.kind === "rest");
    if (restIndex !== -1 && restIndex !== segments.length - 1) {
        throw new Error(`Route pattern "${pattern}" may only use a catch-all (*name) as the last segment.`);
    }
    return segments;
}
function splitPath(path) {
    return path.split("/").filter((part) => part !== "");
}
function matchSegments(segments, pathSegments) {
    const last = segments[segments.length - 1];
    const hasRest = last !== undefined && last.kind === "rest";
    if (hasRest) {
        if (pathSegments.length < segments.length - 1) {
            return undefined;
        }
    }
    else if (segments.length !== pathSegments.length) {
        return undefined;
    }
    const params = {};
    const fixedCount = hasRest ? segments.length - 1 : segments.length;
    for (let i = 0; i < fixedCount; i++) {
        const segment = segments[i];
        const value = pathSegments[i];
        if (segment === undefined || value === undefined) {
            return undefined;
        }
        if (segment.kind === "literal") {
            if (segment.value !== value) {
                return undefined;
            }
        }
        else if (segment.kind === "param") {
            params[segment.name] = decodeURIComponent(value);
        }
    }
    if (hasRest) {
        params[last.name] = pathSegments
            .slice(fixedCount)
            .map((value) => decodeURIComponent(value))
            .join("/");
    }
    return params;
}
